/**
 * China Provincial -> Prefecture -> County 5-Dimension Regional Gazetteer (中国省市县五维特色风物志)
 *
 * Read-only consumption of `regions.catalog.json` (34 provinces / 333 prefectures / 2,845 counties)
 * and `county-pack-01.json` (20 official evidence-pack profiles) without mutating locked JSON files.
 * Currently provides 921 curated seeds + 20 official evidence-pack profiles = 941 deeply curated units
 * (33.08% of 2,845 counties) covering all 34 provincial units with >= 2 deeply curated profiles each,
 * plus honest regional-ecological synthesis baselines for all remaining 2,845 counties (never fabricating local GDP/pop).
 */
