export type VisualMotifId =
  | 'terrace_mountain'
  | 'jiangnan_water'
  | 'grassland_nomad'
  | 'coastal_harbor'
  | 'ancient_town'
  | 'loess_canyon'
  | 'metropolis_hub'
  | 'karst_peak'
  | 'desert_oasis'
  | 'snow_plateau';

export interface CountyFiveDimFeatures {
  politicsGovernance: string;
  economyIndustry: string;
  cultureHeritage: string;
  societyLivelihood: string;
  customsLifestyle: string;
}

export interface CountyGazetteerProfile {
  code: string;
  name: string;
  provinceCode: string;
  provinceName: string;
  prefectureCode: string | null;
  prefectureName: string;
  tags: readonly string[];
  visualMotif: VisualMotifId;
  landmarkKind: LandmarkArchetypeId;
  landmarkName: string;
  accentHex: string;
  dataOrigin: 'official_evidence_pack' | 'curated_gazetteer' | 'provincial_baseline_synthesis';
  provenanceNote: string;
  features: CountyFiveDimFeatures;
  surveyHooks: readonly string[];
}

interface CuratedSeed {
  code: string;
  name?: string;
  provinceCode?: string;
  prefectureName?: string;
  tags: readonly string[];
  visualMotif: VisualMotifId;
  landmarkKind?: LandmarkArchetypeId;
  landmarkName?: string;
  accentHex: string;
  features: CountyFiveDimFeatures;
  surveyHooks: readonly string[];
}

interface ProvincialBaselineSpec {
  motif: VisualMotifId;
  accentHex: string;
  tags: readonly string[];
  features: CountyFiveDimFeatures;
}

