// Index curated seeds and auto-merge official evidence-pack counties (`county-pack-01.json`)
const PACK_PROFILE_BY_CODE = new Map<string, (typeof countyPackData.profiles)[number]>();
for (const rawProfile of countyPackData.profiles) {
  const code = rawProfile.regionRef?.code;
  if (code) PACK_PROFILE_BY_CODE.set(code, rawProfile);
}

const CURATED_BY_CODE = new Map<string, CuratedSeed>();
for (const seed of CURATED_COUNTY_SEEDS) {
  CURATED_BY_CODE.set(seed.code, seed);
}

const RECORD_BY_CODE = new Map<string, RegionRecord>(
  TOPIC_REGION_CATALOG.records.map(r => [r.code, r]),
);

const PROVINCE_LIST = TOPIC_REGION_CATALOG.records.filter(r => r.level === 'province');
const PREFECTURE_LIST = TOPIC_REGION_CATALOG.records.filter(r => r.level === 'prefecture');
const COUNTY_LIST = TOPIC_REGION_CATALOG.records.filter(r => r.level === 'county');

function hashCountyCode(code: string): number {
  let h = 2166136261;
  for (let i = 0; i < code.length; i++) {
    h ^= code.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function buildCountyDifferentiatedTags(
  rec: RegionRecord,
  provBase: ProvincialBaselineSpec,
  badgeTag: string,
): string[] {
  const seed = hashCountyCode(rec.code);
  const name = rec.name;
  let roleTag = '';

  if (/自治县|自治旗|林区|矿区/u.test(name)) {
    const opts = ['民族非遗共融', '边疆生态样本', '林草康养带'];
    roleTag = opts[seed % opts.length];
  } else if (/港|海|湾|岛|滩|澳|潮|礁/u.test(name)) {
    const opts = ['向海临港经济', '滨海渔旅融合', '海丝口岸节律'];
    roleTag = opts[seed % opts.length];
  } else if (/山|岭|峰|岩|茶|竹|松|林|坪|谷/u.test(name)) {
    const opts = ['山地林茶产区', '森林康养民宿', '生态农旅示范'];
    roleTag = opts[seed % opts.length];
  } else if (/河|江|湖|浦|溪|水|塘|池|泽|洲/u.test(name)) {
    const opts = ['水系农旅廊道', '流域城镇协同', '滨水宜居样本'];
    roleTag = opts[seed % opts.length];
  } else if (/区$/u.test(name)) {
    const opts = ['主城消费腹地', '都市社区更新', '产城科创板块', '城市夜间零售'];
    roleTag = opts[seed % opts.length];
  } else if (/市$/u.test(name)) {
    const opts = ['县级产城枢纽', '商贸物流节点', '制造业强县'];
    roleTag = opts[seed % opts.length];
  } else {
    const opts = ['农旅共富样本', '县域电商下沉', '镇村集市单元', '县城安居样本', '特色农工强县', '乡村治理一线'];
    roleTag = opts[seed % opts.length];
  }

  const provTag = provBase.tags[seed % provBase.tags.length];
  const dedup = new Set<string>([roleTag, badgeTag, provTag]);
  return [...dedup];
}

function sanitizeQualitativePackFacts(facts: (typeof countyPackData.profiles)[number]['facts']): string {
  const raw = (facts ?? []).map(f => f.text).join(' ').trim();
  if (!raw) return '';
  return raw
    .replace(/；定位为第\d+项、物理第\d+页。/g, '。')
    .replace(/\d+年度第四批名单列有/g, '工信部国家级中小企业特色产业集群名单列有')
    .replace(/数据截止\d+年\d+月\d+日的文旅部乡村旅游重点村页面列有/g, '文旅部全国乡村旅游重点村名录列有')
    .replace(/县农业农村局\d+年的信息介绍\d+年/g, '县农业农村局公开信息介绍近年')
    .replace(/县人社局\d+年度工作报告/g, '县人社局年度工作报告')
    .replace(/旗文旅部门\d+年的旅游概况/g, '旗文旅部门公开旅游概况')
    .replace(/州人大网站\d+年的报道/g, '州人大公开报道')
    .replace(/\d+年(?:\d+月)?政府工作报告/g, '当地政府工作报告')
    .replace(/\d+年(?:\d+月)?的(?:部门报道|市工信局报道|国家发改委案例|生态环境部门报道)/g, (_m, org) => `${org}近期公开`)
    .replace(/\d+年(?:\d+月)?的/g, '近期公开')
    .replace(/\d+年(?:\d+月)?/g, '近年')
    .replace(/\d+/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function mergeOfficialPackIntoFeatures(
  packEntry: (typeof countyPackData.profiles)[number],
  provBase: ProvincialBaselineSpec,
  prefName: string,
): CountyGazetteerProfile {
  const rec = getRegionByCode(packEntry.regionRef!.code)!;
  const prov = getRegionByCode(rec.provinceCode)!;
  const landmark = resolveCountyLandmark({
    code: rec.code,
    name: rec.name,
    provinceCode: prov.code,
    prefectureCode: rec.parentCode === prov.code ? null : rec.parentCode,
    prefectureName: prefName,
    visualMotif: provBase.motif,
  });
  const tags = [
    ...(packEntry.tags ?? []).map(t => t.label),
    landmark.badgeTag,
    ...provBase.tags.filter(t => !(packEntry.tags ?? []).some(pt => pt.label === t)),
  ].slice(0, 4);
  const factsText = sanitizeQualitativePackFacts(packEntry.facts);
  const hooks = (packEntry.directions ?? []).map(d => `${d.title}：${d.question}`).slice(0, 3);
  return {
    code: rec.code,
    name: packEntry.displayName || rec.name,
    provinceCode: prov.code,
    provinceName: prov.name,
    prefectureCode: rec.parentCode === prov.code ? null : rec.parentCode,
    prefectureName: prefName,
    tags,
    visualMotif: provBase.motif,
    landmarkKind: landmark.kind,
    landmarkName: landmark.landmarkName,
    accentHex: provBase.accentHex,
    dataOrigin: 'official_evidence_pack',
    provenanceNote: `官方核验证据包（county-pack-01 · 含公开政务/文旅档案时间标定）`,
    features: {
      politicsGovernance: provBase.features.politicsGovernance,
      economyIndustry: factsText
        ? `${factsText.slice(0, 140)}${factsText.length > 140 ? '…' : ''}`
        : provBase.features.economyIndustry,
      cultureHeritage: (packEntry.tags ?? []).map(t => t.label).join('、')
        ? `重点围绕“${(packEntry.tags ?? []).map(t => t.label).join('、')}”及地标“${landmark.landmarkName}”承载文化脉络，${provBase.features.cultureHeritage}`
        : provBase.features.cultureHeritage,
      societyLivelihood: packEntry.directions?.[0]?.population
        ? `重点关注人群：${packEntry.directions[0].population}；${provBase.features.societyLivelihood}`
        : provBase.features.societyLivelihood,
      customsLifestyle: provBase.features.customsLifestyle,
    },
    surveyHooks: hooks.length
      ? hooks
      : [`${packEntry.displayName}公共服务体验与民生满意基线调查`],
  };
}

function buildSynthesizedCountyProfile(rec: RegionRecord): CountyGazetteerProfile {
  const prov = RECORD_BY_CODE.get(rec.provinceCode) ?? rec;
  const parent = rec.parentCode ? RECORD_BY_CODE.get(rec.parentCode) : undefined;
  const prefName = parent && parent.level === 'prefecture' ? parent.name : `${prov.name}直属管辖单元`;
  const prefCode = parent && parent.level === 'prefecture' ? parent.code : null;
  const provBase = PROVINCIAL_BASELINES[rec.provinceCode] ?? PROVINCIAL_BASELINES['330000'];
  const landmark = resolveCountyLandmark({
    code: rec.code,
    name: rec.name,
    provinceCode: prov.code,
    prefectureCode: prefCode,
    prefectureName: prefName,
    visualMotif: provBase.motif,
  });

  const isAuto = /自治县|自治旗|林区|矿区/u.test(rec.name);
  const isCity = /市$/u.test(rec.name);
  const isDistrict = /区$/u.test(rec.name);
  const countyKindCue = isAuto
    ? '民族自治/特殊生态功能区特色显著，宜聚焦双语文化传承、生态补偿惠民与农旅融合。'
    : isCity
      ? '作为区域性重要县级市枢纽，城镇常住集中与镇村物流辐射兼具较高市场活跃度。'
      : isDistrict
        ? '作为地市主城/重点功能区组成板块，社区老龄照护、通勤零售及公共服务触达最具实证研究价值。'
        : '作为典型农业/生态或县域经济实体单元，重点观察乡村电商下沉、基础设施均等化与县城消费留存。';

  return {
    code: rec.code,
    name: rec.name,
    provinceCode: prov.code,
    provinceName: prov.name,
    prefectureCode: prefCode,
    prefectureName: prefName,
    tags: buildCountyDifferentiatedTags(rec, provBase, landmark.badgeTag),
    visualMotif: provBase.motif,
    landmarkKind: landmark.kind,
    landmarkName: landmark.landmarkName,
    accentHex: provBase.accentHex,
    dataOrigin: 'provincial_baseline_synthesis',
    provenanceNote: `区域生态基线综合（源于 ${prov.name}·${prefName} 省级谱系特征，田野调研请补充实地核验，绝不编造当地 GDP 或人口数字）`,
    features: {
      politicsGovernance: `${prefName}${rec.name}立足${provBase.features.politicsGovernance}`,
      economyIndustry: `${countyKindCue}（所属区域脉络：${provBase.features.economyIndustry}）`,
      cultureHeritage: `以“${landmark.landmarkName}”建筑风貌意象为区域符号，承接${prov.name}${provBase.features.cultureHeritage}`,
      societyLivelihood: provBase.features.societyLivelihood,
      customsLifestyle: provBase.features.customsLifestyle,
    },
    surveyHooks: [
      `${rec.name}基层公共服务便民度与数字包容（银发/返乡青年视角）调研`,
      `${prefName}${rec.name}县域即时消费、冷链物流触达及本地土特产电商溢价分析`,
      `${rec.name}围绕“${landmark.landmarkName}”周边文旅与居民公共空间满意度调查`,
    ],
  };
}

const SPECIAL_CURATED_PROVINCE_ITEMS: Map<string, CountyGazetteerProfile> = new Map();
for (const seed of CURATED_COUNTY_SEEDS) {
  if (!RECORD_BY_CODE.has(seed.code) && seed.provinceCode && seed.name) {
    const prov = RECORD_BY_CODE.get(seed.provinceCode)!;
    const prefName = seed.prefectureName ?? `${prov.name}特区单元`;
    const landmark = resolveCountyLandmark({
      code: seed.code,
      name: seed.name,
      provinceCode: prov.code,
      prefectureCode: null,
      prefectureName: prefName,
      tags: seed.tags,
      visualMotif: seed.visualMotif,
      customLandmarkName: seed.landmarkName,
      customLandmarkKind: seed.landmarkKind,
    });
    SPECIAL_CURATED_PROVINCE_ITEMS.set(seed.code, {
      code: seed.code,
      name: seed.name,
      provinceCode: prov.code,
      provinceName: prov.name,
      prefectureCode: null,
      prefectureName: prefName,
      tags: seed.tags,
      visualMotif: seed.visualMotif,
      landmarkKind: landmark.kind,
      landmarkName: landmark.landmarkName,
      accentHex: seed.accentHex,
      dataOrigin: 'curated_gazetteer',
      provenanceNote: 'EVI-X 深度整理特色地区五维风物谱系（省级/特区精细单元）',
      features: seed.features,
      surveyHooks: seed.surveyHooks,
    });
  }
}

export function getGazetteerStatsSummary() {
  return {
    catalogVersion: TOPIC_REGION_CATALOG.catalogVersion,
    provinceCount: PROVINCE_LIST.length,
    prefectureCount: PREFECTURE_LIST.length,
    countyCount: COUNTY_LIST.length,
    officialPackCount: PACK_PROFILE_BY_CODE.size,
    curatedSeedCount: CURATED_COUNTY_SEEDS.length,
  };
}

export function getProvinceList(): readonly RegionRecord[] {
  return PROVINCE_LIST;
}

export function getPrefecturesForProvince(provinceCode: string): Array<{ code: string; name: string; countyCount: number; isDirect?: boolean }> {
  const prefs = PREFECTURE_LIST.filter(p => p.provinceCode === provinceCode);
  const directCounties = COUNTY_LIST.filter(c => c.provinceCode === provinceCode && c.parentCode === provinceCode);
  const out: Array<{ code: string; name: string; countyCount: number; isDirect?: boolean }> = prefs.map(p => ({
    code: p.code,
    name: p.name,
    countyCount: COUNTY_LIST.filter(c => c.parentCode === p.code).length,
  }));
  if (directCounties.length > 0) {
    out.push({
      code: `${provinceCode}:direct`,
      name: prefs.length === 0 ? '直辖区/县域总表' : '省直管县市单元',
      countyCount: directCounties.length,
      isDirect: true,
    });
  }
  const specialItems = [...SPECIAL_CURATED_PROVINCE_ITEMS.values()].filter(x => x.provinceCode === provinceCode);
  if (out.length === 0 && specialItems.length > 0) {
    out.push({
      code: `${provinceCode}:special`,
      name: '典型风物与街区示范区',
      countyCount: specialItems.length,
      isDirect: true,
    });
  }
  return out;
}

export function getCountiesForSelection(provinceCode: string, prefectureCode?: string | null): CountyGazetteerProfile[] {
  const specialItems = [...SPECIAL_CURATED_PROVINCE_ITEMS.values()].filter(x => x.provinceCode === provinceCode);
  if (prefectureCode === `${provinceCode}:special`) return specialItems;

  const isDirectFilter = prefectureCode === `${provinceCode}:direct`;
  const matching = COUNTY_LIST.filter(c => {
    if (c.provinceCode !== provinceCode) return false;
    if (!prefectureCode) return true;
    if (isDirectFilter) return c.parentCode === provinceCode;
    return c.parentCode === prefectureCode;
  });

  const profiles = matching.map(rec => getCountyProfile(rec.code)!).filter(Boolean);
  if (!prefectureCode && profiles.length === 0 && specialItems.length > 0) {
    return specialItems;
  }
  return profiles;
}

export function getCountyProfile(code: string): CountyGazetteerProfile | undefined {
  if (SPECIAL_CURATED_PROVINCE_ITEMS.has(code)) {
    return SPECIAL_CURATED_PROVINCE_ITEMS.get(code);
  }
  const rec = RECORD_BY_CODE.get(code);
  if (!rec || rec.level !== 'county') return undefined;

  const prov = RECORD_BY_CODE.get(rec.provinceCode)!;
  const pathNodes = regionPath(rec.code);
  const pref = pathNodes.find(n => n.level === 'prefecture');
  const prefName = pref ? pref.name : `${prov.name}直属管辖`;
  const provBase = PROVINCIAL_BASELINES[rec.provinceCode] ?? PROVINCIAL_BASELINES['330000'];

  const seed = CURATED_BY_CODE.get(rec.code);
  if (seed) {
    const landmark = resolveCountyLandmark({
      code: rec.code,
      name: rec.name,
      provinceCode: prov.code,
      prefectureCode: pref ? pref.code : null,
      prefectureName: prefName,
      tags: seed.tags,
      visualMotif: seed.visualMotif,
      customLandmarkName: seed.landmarkName,
      customLandmarkKind: seed.landmarkKind,
    });
    return {
      code: rec.code,
      name: rec.name,
      provinceCode: prov.code,
      provinceName: prov.name,
      prefectureCode: pref ? pref.code : null,
      prefectureName: prefName,
      tags: seed.tags,
      visualMotif: seed.visualMotif,
      landmarkKind: landmark.kind,
      landmarkName: landmark.landmarkName,
      accentHex: seed.accentHex,
      dataOrigin: 'curated_gazetteer',
      provenanceNote: `EVI-X 精编特色县域五维志（区划代码 ${rec.code}）`,
      features: seed.features,
      surveyHooks: seed.surveyHooks,
    };
  }

  const official = PACK_PROFILE_BY_CODE.get(rec.code);
  if (official) {
    return mergeOfficialPackIntoFeatures(official, provBase, prefName);
  }

  return buildSynthesizedCountyProfile(rec);
}

export function getAllCuratedProfiles(): CountyGazetteerProfile[] {
  const out: CountyGazetteerProfile[] = [];
  const seen = new Set<string>();
  for (const seed of CURATED_COUNTY_SEEDS) {
    const p = getCountyProfile(seed.code);
    if (p && !seen.has(p.code)) {
      seen.add(p.code);
      out.push(p);
    }
  }
  for (const code of PACK_PROFILE_BY_CODE.keys()) {
    const p = getCountyProfile(code);
    if (p && !seen.has(p.code)) {
      seen.add(p.code);
      out.push(p);
    }
  }
  return out;
}

export function searchCountyGazetteer(
  query: string,
  options?: { provinceCode?: string; dimension?: GazetteerDimensionId; limit?: number },
): CountyGazetteerProfile[] {
  const q = query.trim().toLowerCase();
  const limit = Math.min(60, Math.max(1, options?.limit ?? 24));
  const pCode = options?.provinceCode || '';
  const dim = options?.dimension ?? 'all';

  // Priority pool: curated + official pack first, then full 2,845 counties
  const curatedPool = getAllCuratedProfiles().filter(p => !pCode || p.provinceCode === pCode);
  if (!q) {
    const base = pCode
      ? [...curatedPool, ...getCountiesForSelection(pCode).filter(x => !curatedPool.some(c => c.code === x.code))]
      : curatedPool;
    return base.slice(0, limit);
  }

  const hits: CountyGazetteerProfile[] = [];
  const seen = new Set<string>();
  const matchesDim = (p: CountyGazetteerProfile) => {
    const codePrefix = `${p.code} ${p.prefectureCode ?? ''} ${p.provinceCode}`;
    const hay =
      dim === 'all'
        ? `${codePrefix} ${p.name} ${p.landmarkName} ${p.provinceName} ${p.prefectureName} ${p.tags.join(' ')} ${Object.values(p.features).join(' ')}`
        : `${codePrefix} ${p.name} ${p.landmarkName} ${p.tags.join(' ')} ${p.features[dim]}`;
    return hay.toLowerCase().includes(q);
  };

  for (const p of curatedPool) {
    if (matchesDim(p)) {
      seen.add(p.code);
      hits.push(p);
      if (hits.length >= limit) return hits;
    }
  }

  for (const rec of COUNTY_LIST) {
    if (pCode && rec.provinceCode !== pCode) continue;
    if (seen.has(rec.code)) continue;
    if (
      rec.name.toLowerCase().includes(q) ||
      rec.code.includes(q) ||
      (rec.parentCode ?? '').includes(q) ||
      rec.provinceCode.includes(q)
    ) {
      const prof = getCountyProfile(rec.code);
      if (prof && matchesDim(prof)) {
        seen.add(prof.code);
        hits.push(prof);
        if (hits.length >= limit) return hits;
      }
    }
  }

  return hits;
}

/**
 * Generates an editorial Xuan-paper pure-vector architectural landmark card SVG (`assertTrueVector` safe)
 * reflecting each county's authentic landmark building, harmonious palette, and 5-dimension badge glyphs.
 */
export function renderRegionVisualCardSvg(profile: CountyGazetteerProfile, ink?: FigureInk): string {
  return renderLandmarkCardSvg(
    {
      code: profile.code,
      name: profile.name,
      provinceCode: profile.provinceCode,
      prefectureName: profile.prefectureName,
      kind: profile.landmarkKind,
      landmarkName: profile.landmarkName,
      accentHex: profile.accentHex,
      tags: profile.tags,
    },
    ink,
  );
}

export function buildGazetteerInsert(profile: CountyGazetteerProfile): ReportInsert {
  const f = profile.features;
  const text = [
    `以${profile.provinceName}${profile.prefectureName}${profile.name}（区划代码 ${profile.code}，代表地标“${profile.landmarkName}”）作为一线调研情景锚点，`,
    `在政治与基层治理维度，${f.politicsGovernance}`,
    `在经济与特色产业维度，${f.economyIndustry}`,
    `在文化脉络与非遗维度，${f.cultureHeritage}`,
    `在社会结构与民生特征维度，${f.societyLivelihood}`,
    `在民俗习惯与日常风尚维度，${f.customsLifestyle}`,
    `（资料来源说明：${profile.provenanceNote}。实证采样阶段应以实际调研点统计公报与一手访问核实为准。）`,
  ].join(' ');
  return {
    id: `insert-county-${profile.code}-${Date.now().toString(36)}`,
    node: 'intro.background',
    source: `中国县域风物志 · ${profile.name}`,
    items: [{ kind: 'paragraph', text }],
  };
}

export async function buildGazetteerLandmarkInsert(profile: CountyGazetteerProfile): Promise<ReportInsert> {
  const f = profile.features;
  const stamp = Date.now().toString(36);
  const id = `lib-landmark-${profile.code}-${stamp}`;
  const clip = (s: string) => (s.length > 140 ? `${s.slice(0, 138)}…` : s);
  const headers = ['调研维度', '核心区域特征摘要', '一线切入锚点'];
  const rows: string[][] = [
    ['政治与治理', clip(f.politicsGovernance), clip(profile.surveyHooks[0] ?? '基层政策响应机制')],
    ['经济与产业', clip(f.economyIndustry), clip(profile.surveyHooks[1] ?? '产业链与就业格局')],
    ['文化与非遗', clip(f.cultureHeritage), clip(profile.surveyHooks[2] ?? '在地认同与文旅赋能')],
    ['社会与民生', clip(f.societyLivelihood), '重点人口结构与公共服务可达性'],
    ['民俗与风尚', clip(f.customsLifestyle), '消费节庆习惯与口述信任渠道'],
  ];
  const rawMeta = { id, code: profile.code, landmark: profile.landmarkName, rows };
  const sourceHash = await digestText(JSON.stringify(rawMeta));
  const title = `${profile.provinceName}${profile.prefectureName}${profile.name}·${profile.landmarkName}`.slice(0, 148);
  const unsigned = parseResultSnapshot({
    id,
    title,
    sourceName: `EVI-X 中国县域风物志 · ${profile.code} ${profile.name}（${profile.provenanceNote}）`.slice(0, 238),
    sourceUrl: '',
    sourceHash,
    resultHash: '0'.repeat(64),
    classification: 'public',
    method: 'groups',
    n: 5,
    total: 5,
    headers,
    rows,
    metrics: [{ label: '区域五维锚点数', value: 5 }],
    warnings: [],
    variables: [profile.name, `resource-landmark:${profile.code}`],
  });
  const result = { ...unsigned, resultHash: await digestText(JSON.stringify(resultPayload(unsigned))) };
  const lead = [
    `如[[图:@1]]与[[表:@0]]所示，${profile.provinceName}${profile.prefectureName}${profile.name}（区划代码 ${profile.code}，标志建筑“${profile.landmarkName}”）在经济产业上呈现“${clip(f.economyIndustry)}”，`,
    `在文化社会肌理上兼具“${clip(f.cultureHeritage)}”与“${clip(f.societyLivelihood)}”特征。`,
    `（资料说明：${profile.provenanceNote}。实证采样阶段应以实际调研点统计公报与一手访问核实为准。）`,
  ].join('');
  return {
    id: `insert-${id}`,
    node: 'intro.background',
    source: `中国县域风物志 · ${profile.name}`,
    items: [
      { kind: 'table', result, caption: `${profile.provinceName}${profile.prefectureName}${profile.name}（${profile.code}）五维区域风物台账` },
      { kind: 'figure', result, caption: `${profile.provinceName}${profile.prefectureName}${profile.name}标志建筑“${profile.landmarkName}”区域情景图录` },
      { kind: 'paragraph', text: lead },
    ],
  };
}

export function buildGazetteerTopicPrompt(profile: CountyGazetteerProfile): string {
  const hooks = profile.surveyHooks.map((h, i) => `${i + 1}. ${h}`).join('\n');
  return [
    `请结合“${profile.provinceName} ${profile.prefectureName} ${profile.name}”（代码 ${profile.code}）的区域五维实际特征，为我生成一版可落地的第十七届“益普索杯”市调大赛选题与分层抽样预案：`,
    `- 产业与经济背景：${profile.features.economyIndustry}`,
    `- 文化与社会特征：${profile.features.cultureHeritage}；${profile.features.societyLivelihood}`,
    `可参考以下备选研究切入视角：\n${hooks}`,
  ].join('\n');
}
